using System;
using System.IO;
using System.Diagnostics;
using System.Threading;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
public sealed class AboutWindow : Window {
 readonly Action installExit;readonly CancellationTokenSource lifetime=new CancellationTokenSource();readonly TextBlock status,versionLine;readonly TextBlock notes;readonly Button check,download;readonly ProgressBar progress;ReleaseInfo release;string installer;bool busy,closed;
 public AboutWindow(Window owner,Action exit){Owner=owner;installExit=exit;Title="关于 AQ Server";Width=540;Height=520;MinWidth=500;MinHeight=500;MaxHeight=SystemParameters.WorkArea.Height-32;WindowStartupLocation=WindowStartupLocation.CenterOwner;ResizeMode=ResizeMode.CanResize;FontFamily=Theme.Chinese;FontSize=15;Background=Theme.Bg;Foreground=Theme.Ink;Resources=Theme.Resources();Icon=owner==null?null:owner.Icon;if(Icon==null)using(var stream=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("AQServer.ico"))Icon=System.Windows.Media.Imaging.BitmapFrame.Create(stream,System.Windows.Media.Imaging.BitmapCreateOptions.PreservePixelFormat,System.Windows.Media.Imaging.BitmapCacheOption.OnLoad);UseLayoutRounding=true;SnapsToDevicePixels=true;TextOptions.SetTextFormattingMode(this,TextFormattingMode.Display);TextOptions.SetTextRenderingMode(this,TextRenderingMode.ClearType);
  var root=new Grid{Margin=new Thickness(30)};for(int i=0;i<5;i++)root.RowDefinitions.Add(new RowDefinition{Height=i==2?new GridLength(1,GridUnitType.Star):GridLength.Auto});Content=root;
  var brand=new Grid{Margin=new Thickness(0,2,0,22)};brand.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(68)});brand.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});brand.Children.Add(new Image{Source=Icon,Width=52,Height=52,VerticalAlignment=VerticalAlignment.Center,HorizontalAlignment=HorizontalAlignment.Left});var heading=new StackPanel{VerticalAlignment=VerticalAlignment.Center};heading.Children.Add(Theme.Text("AQ Server",25,Theme.Ink,false,true));versionLine=Theme.Text("版本 "+AppUpdates.DisplayVersion+" · Windows x64",13,Theme.Muted);versionLine.Margin=new Thickness(0,7,0,0);heading.Children.Add(versionLine);Grid.SetColumn(heading,1);brand.Children.Add(heading);root.Children.Add(brand);
  var intro=new StackPanel{Margin=new Thickness(0,0,0,16)};intro.Children.Add(Theme.Text("设备监控，安静常驻。",16,Theme.Ink));status=Theme.Text("检查新版本，查看更新内容。",13,Theme.Muted);status.Margin=new Thickness(0,10,0,0);status.TextWrapping=TextWrapping.Wrap;intro.Children.Add(status);Grid.SetRow(intro,1);root.Children.Add(intro);
  var card=new Border{Background=Theme.Surface,BorderBrush=Theme.Line,BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(10),Padding=new Thickness(16),Margin=new Thickness(0,0,0,16)};var content=new DockPanel();var title=Theme.Text("本次更新",14,Theme.Ink,false,true);title.Margin=new Thickness(0,0,0,10);DockPanel.SetDock(title,Dock.Top);content.Children.Add(title);notes=new TextBlock{Text="底部资源栏与分栏布局优化\n偏好设置支持应用而不关闭\n与主题一致的托盘快捷菜单\n新增关于、检查更新与完整安装包",TextWrapping=TextWrapping.Wrap,Foreground=Theme.Muted,FontSize=14,LineHeight=23,LineStackingStrategy=LineStackingStrategy.BlockLineHeight,VerticalAlignment=VerticalAlignment.Top};content.Children.Add(new ScrollViewer{Content=notes,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled});card.Child=content;Grid.SetRow(card,2);root.Children.Add(card);
  progress=new ProgressBar{Height=4,Minimum=0,Maximum=100,Foreground=Theme.Accent,Background=Theme.Line,Visibility=Visibility.Collapsed,Margin=new Thickness(0,0,0,14)};Grid.SetRow(progress,3);root.Children.Add(progress);
  var footer=new Grid();footer.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});footer.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});footer.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var site=Theme.Nav("更新网站",()=>Process.Start(new ProcessStartInfo(AppUpdates.Website){UseShellExecute=true}));site.Width=80;site.HorizontalAlignment=HorizontalAlignment.Left;site.ToolTip=AppUpdates.Website;footer.Children.Add(site);check=Theme.Button("检查更新",Check);Grid.SetColumn(check,1);footer.Children.Add(check);download=Theme.Button("下载更新",Download);download.Margin=new Thickness(10,0,0,0);download.Visibility=Visibility.Collapsed;download.BorderBrush=Theme.Accent;Grid.SetColumn(download,2);footer.Children.Add(download);Grid.SetRow(footer,4);root.Children.Add(footer);
  Closed+=(s,e)=>{closed=true;lifetime.Cancel();};
 }
 void Busy(bool value){busy=value;check.IsEnabled=download.IsEnabled=!value;}
 async void Check(){if(busy)return;Busy(true);status.Text="正在检查更新…";try{var info=await AppUpdates.Check(lifetime.Token);if(closed)return;release=info;installer=null;notes.Text=info.notes??"";if(info.ParsedVersion>AppUpdates.CurrentVersion){status.Text="发现新版本 "+info.version;download.Content="下载更新";download.Visibility=Visibility.Visible;}else{status.Text="当前已是最新版本（"+AppUpdates.DisplayVersion+"）";download.Visibility=Visibility.Collapsed;}}catch(Exception ex){if(!closed){status.Text=AppUpdates.FriendlyError(ex);download.Visibility=Visibility.Collapsed;}}finally{if(!closed)Busy(false);}}
 async void Download(){if(busy||release==null)return;if(installer!=null){Install();return;}Busy(true);progress.Value=0;progress.Visibility=Visibility.Visible;status.Text="正在下载更新…";try{installer=await AppUpdates.Download(release,new Progress<double>(value=>{if(!closed&&busy&&progress.Visibility==Visibility.Visible){progress.Value=value;status.Text="正在下载更新 · "+value.ToString("0")+"%";}}),lifetime.Token);if(closed)return;status.Text="下载完成，校验通过。";download.Content="安装并退出";}catch(Exception ex){if(!closed)status.Text=AppUpdates.FriendlyError(ex);}finally{if(!closed){Busy(false);progress.Visibility=Visibility.Collapsed;}}}
 void Install(){if(MessageBox.Show(this,"安装 AQ Server "+release.version+"？\n\n安装时将退出当前程序，终端会话将关闭。服务器配置和本地历史会保留。","安装更新",MessageBoxButton.OKCancel,MessageBoxImage.Question)!=MessageBoxResult.OK)return;try{AppUpdates.VerifyInstaller(installer,release);Process.Start(new ProcessStartInfo(installer,"/UPDATE=1"){UseShellExecute=true});Close();if(installExit!=null)installExit();}catch(Exception ex){status.Text=AppUpdates.FriendlyError(ex);}}
 public void Render(string file){Snapshot.Save((Grid)Content,file,540,520,144,null);}
}
public sealed partial class MonitorWindow { void OpenAbout(){new AboutWindow(this,Exit).ShowDialog();} }
